import{days,times,uid,load,complete,check,validate,demo}from'./engine.js';import{download,save,publication,exportExcel,readFile,rowsOf,parseRows,parseDirectoryRows}from'./io.js';
const $=s=>document.querySelector(s),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
let p=demo(),selected=p.groups.find(g=>!complete(p,g))?.id,day=1,week='both',page=0,tab=location.hash==='#view'?'view':'editor',search='',queueSearch='',only=false,allWeek=false,entity=null,history=[],future=[],pub=null,book=null,preview=null,map={},importKind='groups',pending=null,chosenSlot=0,chosenOption=0;
const cache=localStorage.getItem('moonkeeper-draft');if(cache){try{p=validate(JSON.parse(cache));selected=p.groups.find(g=>!complete(p,g))?.id}catch{}}
let dirty=false;function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),4500)}
function persist(){dirty=true;try{localStorage.setItem('moonkeeper-draft',JSON.stringify(p))}catch{toast('Автокопия недоступна. Сохраните файл проекта.')}}
function mutate(fn){history.push(JSON.stringify(p));if(history.length>40)history.shift();future=[];fn();persist();render()}
function selectGroup(id){selected=id;entity=null;chosenSlot=0;chosenOption=0;focusGroup();render();scrollSlot()}
function focusGroup(){const g=gCurrent();if(!g)return;chosenSlot=g.slots.findIndex(s=>s.options.some(o=>o.day===day));if(chosenSlot<0)chosenSlot=0;const slot=g.slots[chosenSlot];chosenOption=Math.max(0,slot.options.findIndex(o=>o.day===day));day=slot.options[chosenOption].day}
function scrollSlot(){requestAnimationFrame(()=>{const a=proposal('');if(a)document.querySelector(`[data-drop$=":${a.day}:${a.pair}"]`)?.scrollIntoView({block:'nearest',inline:'center',behavior:'smooth'})})}
function shortName(name){const [last,...rest]=name.trim().split(/\s+/);return last+' '+rest.map(x=>x.length>2?x[0]+'.':x).join(' ')}
function options(arr,val){return arr.map(([v,t])=>`<option value="${esc(v)}" ${String(v)===String(val)?'selected':''}>${esc(t)}</option>`).join('')}
function button(action,text,cls=''){return `<button class="${cls}" data-action="${action}">${text}</button>`}
function gCurrent(){return p.groups.find(g=>g.id===selected)}
function proposal(t,room='',sub){const g=gCurrent(),s=g?.slots[chosenSlot],o=s?.options[chosenOption];sub??=Array.from({length:g?.split?2:1},(_,i)=>i+1).find(n=>!p.assignments.some(a=>a.group===g.id&&a.slot===s.id&&a.sub===n))||1;return o?{id:uid(),group:g.id,slot:s.id,sub,teacher:t,room,...o,week:s.week}:null}
function side(){if(entity)return entityForm();const g=gCurrent();if(!g)return '<div class="empty">Выберите группу в очереди или занятие в сетке</div>';chosenSlot=Math.min(chosenSlot,g.slots.length-1);const s=g.slots[chosenSlot];chosenOption=Math.min(chosenOption,s.options.length-1);return `<div class="side-title"><h2>${esc(g.code)}</h2>${button('edit-group','✎')}</div><div class="eyebrow">ПАРАМЕТРЫ ГРУППЫ</div><label>Ходят на английский <input id="count" type="number" min="1" value="${g.count}"></label>${g.count>24?'<div class="notice">Больше 24: доступно деление</div>':''}<label class="inline">Разделить на подгруппы <input id="split" type="checkbox" ${g.split?'checked':''} ${g.count<=24&&!g.split?'disabled':''}></label>${g.split?`<div class="two"><label>1 п/г<input id="size1" type="number" min="1" max="${g.count-1}" value="${g.size1}"></label><label>2 п/г<input disabled value="${g.count-g.size1}"></label></div><small>Два разных преподавателя · одновременно</small>`:''}<h3>Занятие</h3><select id="slot">${options(g.slots.map((s,i)=>[i,`Занятие ${i+1} · ${s.week==='both'?'обе недели':s.week+' неделя'}`]),chosenSlot)}</select><h3>Варианты слота</h3>${s.options.map((o,i)=>`<label class="radio"><input type="radio" name="opt" value="${i}" ${i===chosenOption?'checked':''}><span><b>${days[o.day]} · ${o.pair} пара</b><small>${times[o.pair-1]}</small></span></label>`).join('')}<h3>Назначение</h3><label>${g.split?'Подгруппа':'Состав занятия'}<select id="sub">${options(Array.from({length:g.split?2:1},(_,i)=>[i+1,(g.split?`${i+1} п/г`:'Вся группа')+(p.assignments.some(a=>a.group===g.id&&a.slot===s.id&&a.sub===i+1)?' · назначена':'')]),proposal('')?.sub||1)}</select></label><label>Преподаватель<select id="teacher"><option value="">Выбрать преподавателя</option>${options(p.teachers.filter(t=>!check(p,proposal(t.id)).errors.length).sort((a,b)=>(a.target-load(p,a.id))-(b.target-load(p,b.id))).map(t=>[t.id,`${t.name} · ${load(p,t.id)}/${t.target}`]),'')}</select></label><label>Аудитория<select id="room"><option value="">Без аудитории</option>${options(p.rooms.map(r=>[r.id,`${r.name} · ${r.capacity} мест`]),'')}</select></label>${button('assign','Назначить','primary full')}${button('skip','Отложить','full')}<small>${g.split?'Выберите подгруппу и перетащите карточку':'Перетащите карточку'} на преподавателя. Занятые назначения открываются кликом.</small><h3>Уже назначено</h3>${p.assignments.filter(a=>a.group===g.id).map(a=>`<div class="assigned">${days[a.day]} ${a.pair} · ${g.split?a.sub+' п/г · ':''}${esc(p.teachers.find(t=>t.id===a.teacher)?.name)} ${button('roomedit:'+a.id,'Аудитория')}${button('remove:'+a.id,'Удалить')}</div>`).join('')}`}
function availability(name,title,values){return `<details class="availability"><summary>${title} · отмечено ${values.length}</summary><table><thead><tr><th>День</th>${times.map((_,i)=>`<th>${i+1}</th>`).join('')}</tr></thead><tbody>${days.map((d,i)=>`<tr><th>${d}<br><button type="button" data-whole-day="${name}:${i}">Весь день</button></th>${times.map((_,j)=>`<td><input aria-label="${title}: ${d}, ${j+1} пара" type="checkbox" name="${name}" value="${i}:${j+1}" ${values.includes(i+':'+(j+1))?'checked':''}></td>`).join('')}</tr>`).join('')}</tbody></table></details>`}
function optionFields(o){return `<div class="slot-option"><select data-day>${options(days.map((d,i)=>[i,d]),o.day)}</select><select data-pair>${options(times.map((t,i)=>[i+1,(i+1)+' пара · '+t]),o.pair)}</select><button type="button" data-remove-option>Удалить</button></div>`}
function slotFields(slot,i){return `<fieldset class="slot-editor"><legend>Занятие ${i+1}</legend><label>Недели<select data-week>${options([['both','Обе недели'],['I','I неделя'],['II','II неделя']],slot.week)}</select></label><div class="slot-options">${slot.options.map(optionFields).join('')}</div><button type="button" data-add-option>Добавить вариант времени</button><button type="button" data-any-day>Любой день на этой паре</button><button type="button" data-remove-slot>Удалить занятие</button></fieldset>`}
function bindSlotButtons(){document.querySelectorAll('[data-any-day]').forEach(b=>b.onclick=()=>{const field=b.closest('fieldset'),pair=+field.querySelector('[data-pair]').value;field.querySelector('.slot-options').innerHTML=days.map((_,day)=>optionFields({day,pair})).join('');bindSlotButtons()});document.querySelectorAll('[data-whole-day]').forEach(b=>b.onclick=()=>{const[name,d]=b.dataset.wholeDay.split(':');const checks=[...document.querySelectorAll(`input[name="${name}"]`)].filter(c=>c.value.startsWith(d+':'));const all=checks.every(c=>c.checked);checks.forEach(c=>c.checked=!all)});document.querySelectorAll('[data-add-option]').forEach(b=>b.onclick=()=>{b.closest('fieldset').querySelector('.slot-options').insertAdjacentHTML('beforeend',optionFields({day,pair:1}));bindSlotButtons()});document.querySelectorAll('[data-remove-option]').forEach(b=>b.onclick=()=>{if(b.closest('.slot-options').children.length>1)b.closest('.slot-option').remove();else toast('У занятия должен остаться хотя бы один вариант')});document.querySelectorAll('[data-remove-slot]').forEach(b=>b.onclick=()=>{if(document.querySelectorAll('.slot-editor').length>1)b.closest('fieldset').remove();else toast('Нужно хотя бы одно занятие')})}
function entityForm(){const{kind,id}=entity,x=p[kind].find(x=>x.id===id);if(!x)return '';const isT=kind==='teachers',isR=kind==='rooms';return `<div class="side-title"><h2>${isT?'Преподаватель':isR?'Аудитория':'Группа'}</h2>${button('close-entity','×')}</div><form id="entity-form"><label>${isT?'ФИО':isR?'Аудитория':'Код группы'}<input name="name" required value="${esc(isT?x.name:isR?x.name:x.code)}"></label>${isT?`<label>Должность<input name="position" value="${esc(x.position)}"></label><div class="two"><label>Ставка<input name="rate" type="number" min="0.1" step="0.1" value="${x.rate}"></label><label>Норма пар/нед.<input name="target" type="number" step="0.5" min="0" value="${x.target}"></label></div><small>Норма задаётся индивидуально, ставка не пересчитывает её автоматически.</small>${availability('blocked','Недоступное время',x.blocked)}${availability('avoid','Нежелательное время',x.avoid)}<label>Желаемые группы<input name="wants" value="${esc((x.wants||[]).join(','))}"></label>`:isR?`<label>Вместимость<input name="capacity" type="number" min="1" value="${x.capacity}"></label>`:`<label>Ходят на английский<input name="count" type="number" min="1" value="${x.count}"></label><label class="inline"><input name="split" type="checkbox" ${x.split?'checked':''}>Разделить на две подгруппы</label><label>Человек в первой подгруппе<input name="size1" type="number" min="1" value="${x.size1}"></label><h3>Занятия и допустимое время</h3><div id="slot-fields">${x.slots.map((slot,i)=>slotFields(slot,i)).join('')}</div><button type="button" data-action="add-slot">Добавить занятие</button>`}<button class="primary full">Сохранить карточку</button></form>${button('delete-entity','Удалить карточку','danger full')}`}
function visible(a){return week==='both'||a.week==='both'||a.week===week}
function grid(){let teachers=p.teachers.filter(t=>t.name.toLowerCase().includes(search.toLowerCase()));if(only&&gCurrent())teachers=teachers.filter(t=>!check(p,proposal(t.id)).errors.length);let cols=allWeek?days.flatMap((_,d)=>times.map((_,i)=>({d,pair:i+1}))):times.map((_,i)=>({d:day,pair:i+1}));return `<div class="grid-scroll"><table class="schedule ${allWeek?'wide':''}"><thead><tr><th>Преподаватель <small>Средняя нагрузка / норма</small></th>${cols.map(c=>`<th>${allWeek?days[c.d]+' · ':''}${c.pair}<small>${times[c.pair-1]}</small></th>`).join('')}</tr></thead><tbody>${teachers.map(t=>`<tr><th><button class="teacher" data-entity="teachers:${esc(t.id)}"><b>${esc(shortName(t.name))}</b><span>${load(p,t.id)} / ${t.target}</span><small>${esc(t.position)} · ${t.rate} ставки</small><progress max="${Math.max(t.target,load(p,t.id),1)}" value="${load(p,t.id)}"></progress></button></th>${cols.map(c=>{let aa=p.assignments.filter(a=>a.teacher===t.id&&a.day===c.d&&a.pair===c.pair&&visible(a)),a=proposal(t.id),candidate=a&&a.day===c.d&&a.pair===c.pair&&!check(p,a).errors.length,blocked=t.blocked.includes(`${c.d}:${c.pair}`);return `<td data-drop="${esc(t.id)}:${c.d}:${c.pair}" class="${blocked?'blocked':candidate?'eligible':''}">${aa.map(a=>`<button class="lesson ${a.week==='both'?'':'half'}" data-lesson="${esc(a.id)}"><b>${esc(p.groups.find(g=>g.id===a.group)?.code)}</b><small>${p.groups.find(g=>g.id===a.group)?.split?a.sub+' п/г · ':''}${a.week==='both'?'I + II':a.week} · ${esc(p.rooms.find(r=>r.id===a.room)?.name||'Без аудитории')}</small></button>`).join('')|| (blocked?'<small>Недоступно</small>':candidate?`<button class="slot-action" data-place="${esc(t.id)}:${c.d}:${c.pair}">Назначить</button>`:'')}${candidate&&t.avoid.includes(`${c.d}:${c.pair}`)?'<small class="warning">Нежелательная пара</small>':''}</td>`}).join('')}</tr>`).join('')}</tbody></table></div><div class="grid-foot">Показано ${teachers.length} из ${p.teachers.length} преподавателей · ${allWeek?'Обзор недели':'Перетащите группу в подсвеченный слот'}</div>`}
function queue(){const rank=g=>{const matching=g.slots.filter(s=>s.options.some(o=>o.day===day));return !matching.length?2:matching.some(s=>new Set(s.options.map(o=>o.day)).size===1)?0:1};const groups=p.groups.filter(g=>!complete(p,g)&&g.code.toLowerCase().includes(queueSearch.toLowerCase())).sort((a,b)=>rank(a)-rank(b));page=Math.min(page,Math.max(0,Math.ceil(groups.length/10)-1));return `<section class="queue"><div class="queue-head"><h2>Очередь групп <em>Осталось ${groups.length}</em></h2><input id="queue-search" placeholder="Найти группу…" value="${esc(queueSearch)}"><span>${groups.length? page*10+1:0}–${Math.min(page*10+10,groups.length)} из ${groups.length}</span>${button('prev','‹')}${button('next','›')}</div><div class="cards">${groups.slice(page*10,page*10+10).map(g=>`<button draggable="true" data-group="${esc(g.id)}" class="group-card ${selected===g.id?'selected':''}"><b>${esc(g.code)}</b><small>${g.count} чел. · ${g.slots.length} занятий</small><span class="${g.count>24?'tag amber':'tag'}">${g.split?'2 подгруппы':g.count>24?'Можно разделить':g.slots[0].options.map(o=>days[o.day]+' · '+o.pair).join(' / ')}</span>${p.assignments.some(a=>a.group===g.id)?'<small>Частично назначена</small>':''}</button>`).join('')||'<div class="empty">Очередь пуста. Все занятия распределены или скрыты поиском.</div>'}</div></section>`}
function render(){let issues=p.assignments.flatMap(a=>{const c=check(p,a,a.id);return c.errors.map(e=>({id:a.id,text:e}))}),noRoom=p.assignments.filter(a=>!a.room).length;$('#app').innerHTML=`<header><div class="brand">☾ <strong>Расписание кафедры</strong></div><input id="title" aria-label="Название проекта" value="${esc(p.title)}"><nav>${['editor','groups','teachers','rooms','import','view'].map((t,i)=>button('tab:'+t,['Редактор','Группы','Преподаватели','Аудитории','Импорт','Просмотр'][i],tab===t?'active':'')).join('')}</nav></header><div class="filebar"><span class="local">● Только на этом устройстве</span>${button('open','Открыть')}${button('save','Сохранить проект','primary')}${button('excel','Excel')}${button('publish','Для просмотра…')}${button('undo','↶ Отмена')}${button('redo','↷ Повтор')}<span class="save-status">${dirty?'Автокопия в браузере · сохраните файл':'Проект открыт'}</span>${button('new','Новый')}${button('demo','Демо')}</div>${pending?roomDialog():''}${tab==='editor'?`${queue()}<main><section class="workspace"><div class="toolbar"><b>Преподаватели</b><input id="search" placeholder="Поиск преподавателя…" value="${esc(search)}"><div class="segments">${['I','II','both'].map(w=>button('week:'+w,w==='both'?'Обе':w,week===w?'active':'')).join('')}</div><div class="segments">${days.map((d,i)=>button('day:'+i,d,day===i?'active':'')).join('')}</div><label class="inline"><input id="allweek" type="checkbox" ${allWeek?'checked':''}>Вся неделя</label><label class="inline"><input id="only" type="checkbox" ${only?'checked':''}>Подходящие</label></div>${grid()}<details class="checks"><summary>Распределено ${p.assignments.length} · Конфликты: ${issues.length} · Без аудиторий: ${noRoom}</summary>${issues.map(x=>`<p><button data-lesson="${esc(x.id)}">${esc(x.text)}</button></p>`).join('')||'<p>Пересечений и нарушений слотов не обнаружено.</p>'}<small>Пожелания и превышения нормы показаны при назначении. Нагрузка считается в среднем за двухнедельный цикл.</small></details></section><aside>${side()}</aside></main>`:tab==='view'?view():tab==='import'?importView():directory()}<footer>Moonkeeper Schedule · Локальная обработка · Файлы не отправляются на сервер</footer>`;bind()}
function directory(){const kind=tab,x=p[kind];return `<main><section class="workspace directory"><div class="queue-head"><h2>${{groups:'Группы',teachers:'Преподаватели',rooms:'Аудитории'}[kind]}</h2>${button('add:'+kind,'＋ Добавить','primary')}</div><div class="directory-list">${x.map(v=>`<button class="directory-card" data-entity="${kind}:${esc(v.id)}"><b>${esc(v.name||v.code)}</b><small>${kind==='teachers'?`${load(p,v.id)} / ${v.target} пар · ${v.rate} ставки`:kind==='rooms'?`${v.capacity} мест`:`${v.count} чел. · ${v.slots.length} занятий · ${complete(p,v)?'готово':'в очереди'}`}</small></button>`).join('')}</div></section><aside>${entity?entityForm():'<div class="empty">Выберите карточку для редактирования</div>'}</aside></main>`}
function view(){const v=pub||publication(p),t=v.teachers.find(t=>t.id===localStorage.getItem('moonkeeper-view-teacher'))||v.teachers[0];return `<section class="viewer"><div class="queue-head"><div><h1>${esc(v.title)}</h1><small>${pub?'Опубликовано '+esc(new Date(v.publishedAt).toLocaleString('ru')):'Предпросмотр текущего проекта'}</small></div>${button('open','Открыть файл публикации')}${button('print','Печать')}</div><label>Преподаватель<select id="viewer-teacher">${options(v.teachers.map(x=>[x.id,x.name]),t?.id)}</select></label><div class="week-view">${days.map((d,i)=>`<article><h3>${d}</h3>${v.lessons.filter(a=>a.teacher===t?.id&&a.day===i).sort((a,b)=>a.pair-b.pair).map(a=>`<div class="view-lesson"><b>${a.pair} пара · ${times[a.pair-1]}</b><p>${esc(a.group)} · ${a.split?' · '+a.sub+' п/г':''}</p><small>${esc(a.room)} · ${a.week==='both'?'Обе недели':a.week+' неделя'}</small></div>`).join('')||'<small>Нет занятий</small>'}</article>`).join('')}</div></section>`}
function importView(){if(!book)return `<section class="import-page"><h1>Импорт исходных данных</h1><p>Файл проекта JSON или Excel, созданный приложением, восстанавливается целиком. Для других таблиц выберите лист и сопоставьте столбцы.</p>${button('open','Выбрать Excel / CSV / JSON','primary')}<h3>Табличный формат исходного расписания</h3><p>Также можно импортировать преподавателей (ФИО, должность, ставка, норма) и аудитории (название, вместимость). Тип выбирается после открытия файла.</p><p>Одна строка — одно занятие: Группа, Численность, День, Пара, Неделя (I / II / both).</p><p>Несколько строк одной группы создают несколько занятий. Альтернативные слоты выбираются в форме карточки группы. Сложные матричные таблицы учебных отделов требуют отдельного профиля парсера.</p>${button('template','Скачать пример CSV')}</section>`;const rows=rowsOf(book,book.selected||book.SheetNames[0]),cols=Object.keys(rows[0]||{});return `<section class="import-page"><h1>Предпросмотр импорта</h1><label>Лист<select id="sheet">${options(book.SheetNames.map(n=>[n,n]),book.selected||book.SheetNames[0])}</select></label><label>Что импортируем<select id="import-kind">${options([['groups','Группы и занятия'],['teachers','Преподаватели'],['rooms','Аудитории']],importKind)}</select></label><div class="mapping">${(importKind==='teachers'?[['name','Полные ФИО'],['position','Должность'],['rate','Ставка (необязательно)'],['target','Норма пар/нед.']]:importKind==='rooms'?[['name','Аудитория'],['capacity','Число мест']]:[['group','Группа'],['count','Численность'],['day','День'],['pair','Пара'],['week','Неделя']]).map(([k,t])=>`<label>${t}<select data-map="${k}"><option value="">— выбрать —</option>${options(cols.map(c=>[c,c]),map[k]||'')}</select></label>`).join('')}</div>${button('preview','Проверить строки','primary')}${preview?`<p>Найдено карточек: ${preview.items.length}. Ошибок: ${preview.errors.length}</p>${preview.errors.slice(0,30).map(e=>`<p class="error">${esc(e)}</p>`).join('')}<div class="preview-table">${preview.items.slice(0,30).map(g=>`<p>${esc(g.code||g.name)} · ${esc(g.count??g.target??g.capacity)}</p>`).join('')}</div>${button('apply-import','Добавить карточки','primary')}`:''}<h3>Первые строки источника</h3><pre>${esc(JSON.stringify(rows.slice(0,4),null,2))}</pre></section>`}
function roomDialog(){const a=pending;return `<div class="modal-shade"><section class="room-dialog" role="dialog" aria-modal="true"><h2>Выберите аудиторию</h2><p>${esc(p.groups.find(g=>g.id===a.group)?.code)} · ${days[a.day]} · ${a.pair} пара</p><label>Свободная аудитория<select id="pending-room"><option value="">Выберите помещение</option>${options(p.rooms.filter(r=>!check(p,{...a,room:r.id},a.id).errors.length).map(r=>[r.id,r.name+' · '+r.capacity+' мест']),a.room)}</select></label><small>Если помещений пока нет, добавьте их во вкладке «Аудитории».</small>${button('finish-room','Назначить с аудиторией','primary full')}${button('without-room','Сохранить без аудитории','full')}${button('cancel-room','Отмена','full')}</section></div>`}
function commitAssignment(a){const c=check(p,a,p.assignments.some(x=>x.id===a.id)?a.id:undefined);if(c.errors.length){toast(c.errors.join(' · '));return}const warnings=c.warnings.filter(x=>!['Преподаватель просил эту группу','Не назначена аудитория'].includes(x));if(warnings.length&&!confirm(warnings.join('\n')+'\nСохранить назначение?'))return;pending=null;mutate(()=>{p.assignments=p.assignments.filter(x=>x.id!==a.id);p.assignments.push(a)});toast('Занятие назначено')}
function assignTo(t,d,pair){let a=proposal(t,$('#room')?.value||'',Number($('#sub')?.value||proposal(t)?.sub||1));if(!a)return;if(a.day!==d||a.pair!==pair){toast('Выберите допустимый вариант времени справа');return}const c=check(p,a);if(c.errors.length){toast(c.errors.join(' · '));return}if(!a.room){pending=a;render();return}commitAssignment(a)}
function openLesson(id){const a=p.assignments.find(a=>a.id===id);if(!a)return;selectGroup(a.group);toast('Назначение выбрано. Чтобы переназначить, удалите его в панели справа.');}
async function action(a){if(a.startsWith('roomedit:')){pending={...p.assignments.find(x=>x.id===a.slice(9))};render();return}if(a.startsWith('tab:')){tab=a.slice(4);entity=null;render();return}if(a.startsWith('day:')){day=+a.slice(4);page=0;render();return}if(a.startsWith('week:')){week=a.slice(5);render();return}if(a.startsWith('remove:')){mutate(()=>p.assignments=p.assignments.filter(x=>x.id!==a.slice(7)));return}if(a.startsWith('add:')){const kind=a.slice(4),id=uid();mutate(()=>{p[kind].push(kind==='teachers'?{id,name:'Новый преподаватель',position:'Преподаватель',rate:1,target:12,blocked:[],avoid:[],wants:[]}:kind==='rooms'?{id,name:'Новая аудитория',capacity:24}:{id,code:'Новая группа',count:24,split:false,size1:12,slots:[{id:uid(),week:'both',options:[{day:0,pair:1}]}]});entity={kind,id}});return}switch(a){case'finish-room':if(!$('#pending-room').value){toast('Выберите аудиторию');break}commitAssignment({...pending,room:$('#pending-room').value});break;case'without-room':commitAssignment({...pending,room:''});break;case'cancel-room':pending=null;render();break;case'add-slot':{const el=document.createElement('div');el.innerHTML=slotFields({week:'both',options:[{day, pair:1}]},document.querySelectorAll('.slot-editor').length);$('#slot-fields').append(el.firstElementChild);bindSlotButtons();break}case'open':$('#file').click();break;case'save':save(p);dirty=false;render();break;case'excel':exportExcel(p);break;case'publish':if(confirm('Это файл только для просмотрщика: без пожеланий и рабочей очереди. Он не заменяет сохранение проекта и ничего не загружает на сервер. Скачать?'))download('schedule-publication.json',JSON.stringify(publication(p),null,2));break;case'print':window.print();break;case'prev':page=Math.max(0,page-1);render();break;case'next':page++;render();break;case'skip':{const g=gCurrent();if(g)mutate(()=>{p.groups=p.groups.filter(x=>x.id!==g.id).concat(g);selected=p.groups.find(x=>!complete(p,x)&&x.id!==g.id)?.id});break}case'undo':if(history.length){future.push(JSON.stringify(p));p=JSON.parse(history.pop());persist();render()}break;case'redo':if(future.length){history.push(JSON.stringify(p));p=JSON.parse(future.pop());persist();render()}break;case'edit-group':entity={kind:'groups',id:selected};render();break;case'close-entity':entity=null;render();break;case'delete-entity':{const{kind,id}=entity;if(!confirm('Удалить карточку и связанные назначения?'))return;mutate(()=>{p[kind]=p[kind].filter(x=>x.id!==id);p.assignments=p.assignments.filter(a=>a[{groups:'group',teachers:'teacher',rooms:'room'}[kind]]!==id);entity=null});break}case'assign':{const t=$('#teacher').value,a=proposal(t);if(!t){toast('Выберите преподавателя');return}assignTo(t,a.day,a.pair);break}case'new':case'demo':if(confirm('Текущая работа будет заменена. Сохранили файл проекта?')){mutate(()=>{p=a==='demo'?demo():{schema:1,title:'Новый семестр',teachers:[],groups:[],rooms:[],assignments:[]};selected=p.groups[0]?.id;entity=null;pub=null});}break;case'template':download('groups-template.csv','\uFEFFГруппа,Численность,День,Пара,Неделя\nИКБО-31-26,28,Вт,3,both\nБСБО-11-26,22,Чт,4,I\n','text/csv;charset=utf-8');break;case'preview':{const rows=rowsOf(book,book.selected||book.SheetNames[0]);preview=importKind==='groups'?parseRows(rows,map):parseDirectoryRows(rows,map,importKind);preview.items=preview.groups||preview.items;render();break}case'apply-import':if(!preview||preview.errors.length){toast('Сначала исправьте все ошибки в исходном файле');break}if(preview.items.some(g=>p[importKind].some(x=>(x.code||x.name)===(g.code||g.name)))){toast('Карточка с таким именем уже существует. Повторный импорт пока не объединяет данные.');break}mutate(()=>{p[importKind].push(...preview.items);if(importKind==='groups')selected=preview.items[0]?.id;preview=null;book=null;tab=importKind==='groups'?'editor':importKind});break}}
function bindGrid(){document.querySelectorAll('[data-drop]').forEach(td=>{td.ondragover=e=>e.preventDefault();td.ondrop=e=>{e.preventDefault();const id=e.dataTransfer.getData('text/plain');if(id!==selected)return;const[t,d,pair]=td.dataset.drop.split(':');assignTo(t,+d,+pair)}});document.querySelectorAll('[data-place]').forEach(b=>b.onclick=()=>{const[t,d,pair]=b.dataset.place.split(':');assignTo(t,+d,+pair)})}
function bind(){bindSlotButtons();document.querySelectorAll('[data-action]').forEach(b=>b.onclick=()=>{try{action(b.dataset.action)}catch(e){toast(e.message)}});document.querySelectorAll('[data-group]').forEach(b=>{b.onclick=()=>selectGroup(b.dataset.group);b.ondragstart=e=>{entity=null;if(selected!==b.dataset.group){selected=b.dataset.group;chosenSlot=0;chosenOption=0;focusGroup()}e.dataTransfer.setData('text/plain',b.dataset.group);const holder=document.createElement('div');holder.innerHTML=grid();document.querySelector('.grid-scroll').replaceWith(holder.firstElementChild);document.querySelector('aside').innerHTML=side();document.querySelectorAll('[data-group]').forEach(x=>x.classList.toggle('selected',x.dataset.group===selected));document.querySelectorAll('[data-action^="day:"]').forEach(x=>x.classList.toggle('active',+x.dataset.action.slice(4)===day));bind();scrollSlot()}});document.querySelectorAll('[data-entity]').forEach(b=>b.onclick=()=>{const[kind,id]=b.dataset.entity.split(':');entity={kind,id};render()});document.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(b.dataset.lesson));bindGrid();const on=(id,ev,fn)=>{const el=$('#'+id);if(el)el[ev]=fn};on('search','onchange',e=>{search=e.target.value;render()});on('queue-search','onchange',e=>{queueSearch=e.target.value;page=0;render()});on('title','onchange',e=>mutate(()=>p.title=e.target.value));on('only','onchange',e=>{only=e.target.checked;render()});on('allweek','onchange',e=>{allWeek=e.target.checked;render()});on('slot','onchange',e=>{chosenSlot=+e.target.value;chosenOption=0;day=gCurrent().slots[chosenSlot].options[0].day;render();scrollSlot()});document.querySelectorAll('[name=opt]').forEach(x=>x.onchange=e=>{chosenOption=+e.target.value;day=gCurrent().slots[chosenSlot].options[chosenOption].day;render();scrollSlot()});on('count','onchange',e=>{const n=+e.target.value,g=gCurrent();if(!Number.isInteger(n)||n<1){toast('Нужна положительная целая численность');render();return}mutate(()=>{g.count=n;if(g.split&&g.size1>=n){g.split=false;p.assignments=p.assignments.filter(a=>a.group!==g.id)}g.size1=Math.min(g.size1,Math.max(1,n-1))})});on('split','onchange',e=>{const g=gCurrent(),v=e.target.checked;if(p.assignments.some(a=>a.group===g.id)&&!confirm('Изменение деления удалит назначения этой группы. Продолжить?')){render();return}mutate(()=>{g.split=v;g.size1=Math.ceil(g.count/2);p.assignments=p.assignments.filter(a=>a.group!==g.id)})});on('size1','onchange',e=>{const g=gCurrent(),n=+e.target.value;if(!Number.isInteger(n)||n<1||n>=g.count){render();return}mutate(()=>g.size1=n)});on('viewer-teacher','onchange',e=>{localStorage.setItem('moonkeeper-view-teacher',e.target.value);render()});on('import-kind','onchange',e=>{importKind=e.target.value;preview=null;map={};render()});on('sheet','onchange',e=>{book.selected=e.target.value;preview=null;map={};render()});document.querySelectorAll('[data-map]').forEach(el=>el.onchange=()=>{map[el.dataset.map]=el.value;preview=null});on('entity-form','onsubmit',e=>{e.preventDefault();const f=new FormData(e.target),{kind,id}=entity,x=p[kind].find(x=>x.id===id),copy=structuredClone(p),next=copy[kind].find(x=>x.id===id);try{if(kind==='teachers'){Object.assign(next,{name:f.get('name').trim(),position:f.get('position'),rate:+f.get('rate'),target:+f.get('target'),blocked:f.getAll('blocked'),avoid:f.getAll('avoid'),wants:f.get('wants').split(',').map(x=>x.trim()).filter(Boolean)});if([...next.blocked,...next.avoid].some(x=>!/^([0-5]):([1-7])$/.test(x)))throw Error('Неверный формат ограничений')}else if(kind==='rooms')Object.assign(next,{name:f.get('name').trim(),capacity:+f.get('capacity')});else{const raw=[...document.querySelectorAll('.slot-editor')].map(el=>({week:el.querySelector('[data-week]').value,options:[...el.querySelectorAll('.slot-option')].map(row=>({day:+row.querySelector('[data-day]').value,pair:+row.querySelector('[data-pair]').value}))}));Object.assign(next,{code:f.get('name').trim(),count:+f.get('count'),split:f.has('split'),size1:+f.get('size1'),slots:raw.map((slot,i)=>({...x.slots[i],...slot,id:x.slots[i]?.id||uid()}))});const changed=JSON.stringify(x.slots.map(s=>({week:s.week,options:s.options})))!==JSON.stringify(raw)||x.split!==next.split;if(next.split&&!x.split&&next.count<=24)throw Error('Деление доступно при численности больше 24');if(changed&&p.assignments.some(a=>a.group===id)){if(!confirm('Изменение слотов или деления удалит назначения группы. Продолжить?'))return;copy.assignments=copy.assignments.filter(a=>a.group!==id)}}validate(copy);mutate(()=>p=copy);toast('Карточка сохранена')}catch(err){toast(err.message)}})}
$('#file').onchange=async e=>{try{const file=e.target.files[0];if(!file)return;const result=await readFile(file);if(result.project){if(dirty&&!confirm('Заменить текущий проект? Сначала сохраните его, если нужно.'))return;mutate(()=>{p=result.project;selected=p.groups.find(g=>!complete(p,g))?.id;entity=null;pub=null;tab='editor'});dirty=false}else if(result.publication){const v=result.publication;if(v.schema!==1||!Array.isArray(v.teachers)||!Array.isArray(v.lessons))throw Error('Некорректная публикация');pub=v;tab='view';render()}else{book=result.book;book.selected=book.SheetNames[0];preview=null;map={};tab='import';render()}}catch(err){toast('Не удалось открыть: '+err.message)}finally{e.target.value=''}};
window.addEventListener('beforeunload',e=>{if(dirty){e.preventDefault();e.returnValue=''}});render();
